import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { mkdtemp, readFile, rm, stat, mkdir } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { resolve, relative, extname, join, isAbsolute, sep } from 'node:path'
import { spawnSync } from 'node:child_process'
import { chromium, expect } from '@playwright/test'

// Test-only static server: only generated bytes and the documented SPA fallback.
// This is never a production application server or an API proxy.
async function serve(directory, base) {
  const server = createServer(async (request, response) => {
    try {
      const path = decodeURIComponent(new URL(request.url, 'http://localhost').pathname)
      if (!path.startsWith(base)) { response.writeHead(404).end(); return }
      const target = resolve(directory, path.slice(base.length) || 'index.html')
      const within = relative(directory, target)
      if (within === '..' || within.startsWith(`..${sep}`) || isAbsolute(within)) { response.writeHead(404).end(); return }
      let file = target
      try { if (!(await stat(file)).isFile()) throw new Error('Not a file') }
      catch {
        if (extname(path)) { response.writeHead(404).end(); return }
        file = join(directory, 'index.html')
      }
      response.writeHead(200, { 'Content-Type': ({ '.html': 'text/html', '.js': 'text/javascript', '.css': 'text/css', '.svg': 'image/svg+xml' })[extname(file)] ?? 'application/octet-stream', 'Cache-Control': 'no-store' })
      response.end(await readFile(file))
    } catch { response.writeHead(500).end() }
  })
  await new Promise(resolve => server.listen(0, '127.0.0.1', resolve))
  return { server, origin: `http://127.0.0.1:${server.address().port}` }
}

const artifacts = resolve(process.env.SMOKE_ARTIFACT_DIR ?? 'test-results/static-handoff')
await mkdir(artifacts, { recursive: true })
const scratch = await mkdtemp(join(tmpdir(), 'vndb-static-smoke-'))
let browser
try {
  const subpathDirectory = join(scratch, 'novels')
  const build = spawnSync(process.execPath, ['node_modules/vite/bin/vite.js', 'build', '--base=/novels/', '--outDir', subpathDirectory], { encoding: 'utf8', windowsHide: true })
  assert.equal(build.status, 0, build.stderr || build.stdout)
  browser = await chromium.launch()
  for (const [base, directory] of [['/', resolve('dist')], ['/novels/', subpathDirectory]]) {
    const { server, origin } = await serve(directory, base)
    const context = await browser.newContext({ viewport: { width: 1440, height: 1000 } })
    try {
      const page = await context.newPage()
      const errors = []
      const assets = []
      page.on('pageerror', error => errors.push(error.message))
      page.on('response', response => { if (response.url().startsWith(origin) && /\.(js|css)$/.test(response.url())) assets.push({ url: response.url(), status: response.status() }) })
      const cards = Array.from({ length: 24 }, (_, i) => ({ id: i ? `v${100 + i}` : 'v17', title: i ? `Story ${i + 1}` : 'Handoff story', released: '2003-12-26', rating: 85 - i, image: { url: `https://images.example/${i % 2 ? 'portrait' : 'landscape'}.svg`, dims: i % 2 ? [400, 600] : [600, 400] } }))
      const tags = [{ id: 'g2', name: 'Fantasy', spoiler: 0, searchable: true, description: 'Imaginary worlds.' }, { id: 'g96', name: 'Romance', spoiler: 1, searchable: true, description: 'Relationships between characters.' }]
      const detail = { ...cards[0], description: 'A source story with [b]formatting[/b].\n\nA second paragraph.', aliases: ['A second name'], titles: [], tags, screenshots: [1, 2].map(i => ({ id: `s${i}`, url: `https://images.example/screen${i}.svg`, thumbnail: `https://images.example/screen${i}.svg`, dims: [960, 540], thumbnail_dims: [320, 180] })) }
      const release = { id: 'r1', title: 'First edition', released: '2024', minage: null, official: false, platforms: ['win'], patch: true, languages: [{ lang: 'en', mtl: true }, { lang: 'ru', mtl: false }], vns: [{ id: 'v17', rtype: 'partial' }], extlinks: [{ name: 'website', label: 'Release website', url: 'https://edition.example/' }] }
      await page.route('https://images.example/**', route => route.fulfill({ contentType: 'image/svg+xml', body: `<svg xmlns="http://www.w3.org/2000/svg" width="600" height="${route.request().url().includes('portrait') ? 900 : 400}" viewBox="0 0 600 400"><rect width="600" height="400" fill="#314a50"/><circle cx="360" cy="180" r="140" fill="#eabbd5"/><path d="M0 400 300 70 600 400" fill="#677b50"/></svg>` }))
      await page.route('https://api.vndb.org/kana/**', route => {
        const endpoint = new URL(route.request().url()).pathname.split('/').at(-1)
        const query = route.request().postDataJSON()
        const results = endpoint === 'tag' ? tags : endpoint === 'release' ? query.fields.includes('title') ? [release] : [{ id: release.id, languages: release.languages }] : query.fields.includes('description') ? [detail] : cards
        return route.fulfill({ json: { results, more: endpoint === 'vn' && !query.fields.includes('description') && query.page !== 3, count: endpoint === 'vn' ? 72 : results.length } })
      })
      // Direct HTML5 route and refresh, with actual generated JS/CSS.
      await page.goto(`${origin}${base}vn/v17`)
      await expect(page.getByRole('heading', { name: 'Handoff story', level: 1 })).toBeVisible()
      await page.reload()
      await expect(page.getByRole('heading', { name: 'Handoff story', level: 1 })).toBeVisible()
      await page.goto(`${origin}${base}saved`)
      await expect(page.getByText('Your collection starts here.')).toBeVisible()
      await page.reload()
      await expect(page.getByText('Your collection starts here.')).toBeVisible()

      // Full integrated path: confirmed title/language/tags -> page -> detail ->
      // gallery/releases -> Saved/Undo -> browser Back and the original Catalog.
      await page.goto(`${origin}${base}`)
      await page.getByRole('searchbox', { name: 'Search titles' }).fill('story')
      await page.getByRole('searchbox', { name: 'Search titles' }).press('Enter')
      await page.getByRole('radio', { name: 'Russian', exact: true }).check()
      await page.getByRole('button', { name: 'Browse tags' }).click()
      const picker = page.getByRole('dialog', { name: 'Discover tags' })
      await picker.getByRole('button', { name: 'Include Fantasy', exact: true }).click()
      await picker.getByRole('button', { name: 'Done', exact: true }).click()
      await page.getByRole('button', { name: 'Apply filters', exact: true }).click()
      await page.getByRole('button', { name: 'Page 2', exact: true }).click()
      const catalogUrl = page.url()
      assert(catalogUrl.includes('q=story') && catalogUrl.includes('language=ru') && catalogUrl.includes('tag=g2') && catalogUrl.includes('page=2'))
      await expect(page.getByRole('heading', { name: 'Handoff story', exact: true })).toBeVisible()
      await page.screenshot({ path: join(artifacts, base === '/' ? 'catalog-desktop.png' : 'catalog-subpath.png') })
      await page.getByRole('button', { name: 'Save Handoff story', exact: true }).click()
      await page.getByRole('link', { name: 'Handoff story', exact: true }).click()
      await expect(page.getByRole('button', { name: 'Saved Handoff story', exact: true })).toBeVisible()
      await page.getByRole('button', { name: 'Open screenshot 1', exact: true }).click()
      await page.keyboard.press('ArrowRight')
      await expect(page.getByRole('dialog', { name: 'Screenshot viewer' })).toContainText('Screenshot 2 of 2')
      await page.keyboard.press('Escape')
      await expect(page.getByRole('button', { name: 'Open screenshot 1', exact: true })).toBeFocused()
      await page.getByRole('button', { name: 'English · 1 release', exact: true }).click()
      const english = page.getByRole('region', { name: 'English releases', exact: true })
      await expect(english.getByText('Partial', { exact: true })).toBeVisible()
      await expect(english.getByText('Machine translation', { exact: true })).toBeVisible()
      await expect(english.getByRole('link', { name: 'First edition' })).toHaveAttribute('href', 'https://edition.example/')
      await page.screenshot({ path: join(artifacts, base === '/' ? 'detail-desktop.png' : 'detail-subpath.png'), fullPage: true })
      await page.getByRole('link', { name: 'Saved', exact: true }).click()
      await page.getByRole('button', { name: 'Saved Handoff story', exact: true }).click()
      await expect(page.getByText('Your collection starts here.')).toBeVisible()
      await page.getByRole('button', { name: 'Undo', exact: true }).click()
      await expect(page.getByRole('heading', { name: 'Handoff story', exact: true })).toBeVisible()
      await page.goBack()
      await expect(page.getByRole('heading', { name: 'Handoff story', level: 1 })).toBeVisible()
      await page.getByRole('link', { name: '← Catalog', exact: true }).click()
      await expect(page).toHaveURL(catalogUrl)
      await page.setViewportSize({ width: 390, height: 844 })
      await page.screenshot({ path: join(artifacts, base === '/' ? 'catalog-mobile.png' : 'catalog-subpath-mobile.png') })
      await page.getByRole('button', { name: 'Filters', exact: true }).click()
      await expect(page.getByRole('button', { name: 'Apply filters' })).toBeVisible()
      await page.keyboard.press('Escape')
      await page.getByRole('link', { name: 'Saved', exact: true }).click()
      await expect.poll(() => page.getByRole('img', { name: 'Handoff story cover', exact: true }).evaluate(image => image.complete && image.naturalWidth > 0)).toBe(true)
      await page.screenshot({ path: join(artifacts, base === '/' ? 'saved-mobile.png' : 'saved-subpath-mobile.png'), animations: 'disabled' })
      assert(assets.some(asset => asset.url.endsWith('.js')) && assets.some(asset => asset.url.endsWith('.css')))
      assert(assets.every(asset => asset.status === 200), JSON.stringify(assets))
      assert.deepEqual(errors, [])
      console.log(JSON.stringify({ base, directDetailRefresh: true, directSavedRefresh: true, fullJourney: true, catalogHistory: true, assetResponses: assets.length, pageErrors: errors.length }))
    } finally { await context.close(); await new Promise(resolve => server.close(resolve)) }
  }
} finally { await browser?.close(); await rm(scratch, { recursive: true, force: true }) }
